import pytest
from ucumvert import PintUcumRegistry


@pytest.fixture
def ureg():
    return PintUcumRegistry()


@pytest.mark.parametrize(
    "ucum_code,expected_units_str",
    [
        ("m[IU]/L", "milliinternational_unit / liter"),
        ("k[IU]/L", "kilointernational_unit / liter"),
        ("u[IU]/L", "microinternational_unit / liter"),
        ("n[IU]/L", "nanointernational_unit / liter"),
        ("m[IU]", "milliinternational_unit"),
        ("k[IU]", "kilointernational_unit"),
    ],
)
def test_prefixed_international_units_conversion(ureg, ucum_code, expected_units_str):
    """Test that prefixed international units (like m[IU], k[IU], etc.) convert correctly

    without being misinterpreted as meter * international_unit or kilometer * international_unit.
    """
    quantity = ureg.from_ucum(ucum_code)
    assert str(quantity.units) == expected_units_str
    # Specifically ensure 'meter' is not part of the converted units for m[IU]
    if "m[IU]" in ucum_code:
        assert "meter" not in str(quantity.units)


@pytest.mark.parametrize(
    "ucum_code,expected_units_str",
    [
        ("[IU]", "international_unit"),
        ("[IU]/L", "international_unit / liter"),
        ("m/s", "meter / second"),
        ("kg", "kilogram"),
    ],
)
def test_baseline_units_conversion(ureg, ucum_code, expected_units_str):
    """Ensure baseline conversion behavior for un-prefixed bracketed units

    and standard metric units remains completely unaffected.
    """
    quantity = ureg.from_ucum(ucum_code)
    assert str(quantity.units) == expected_units_str
